package server

import "net/http"

func op(summary, auth string, request, response any) map[string]any {
	o := map[string]any{"summary": summary, "responses": map[string]any{"200": map[string]any{"description": "Success"}, "400": map[string]any{"description": "Invalid request"}, "401": map[string]any{"description": "Authentication required"}, "403": map[string]any{"description": "Forbidden"}, "404": map[string]any{"description": "Not found"}}}
	if auth != "" {
		o["security"] = []any{map[string][]string{auth: {}}}
	}
	if request != nil {
		o["requestBody"] = map[string]any{"required": false, "content": map[string]any{"application/json": map[string]any{"schema": request}}}
	}
	if response != nil {
		o["responses"].(map[string]any)["200"] = map[string]any{"description": "Success", "content": map[string]any{"application/json": map[string]any{"schema": response}}}
	}
	return o
}

